metadata.er-schema:
{
  "title": "looply · 汇率管理 实体关系图",
  "version": "v3.3 · 2026-05-14",
  "tables": [
    {
      "name": "currency",
      "comment": "币种主数据",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "code",
          "comment": "ISO 4217简码",
          "constraint": "UNIQUE"
        },
        {
          "name": "symbol",
          "comment": "币种符号",
          "constraint": ""
        },
        {
          "name": "decimal_precision",
          "comment": "小数精度",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "启停状态",
          "constraint": ""
        }
      ],
      "note": ""
    },
    {
      "name": "exchange_rate_source",
      "comment": "汇率数据源",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "数据源名称",
          "constraint": "UNIQUE"
        },
        {
          "name": "api_url",
          "comment": "API地址",
          "constraint": ""
        },
        {
          "name": "api_key",
          "comment": "API密钥(加密)",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级(主/备)",
          "constraint": ""
        },
        {
          "name": "fetch_interval",
          "comment": "拉取间隔(秒)",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "启停状态",
          "constraint": ""
        },
        {
          "name": "last_fetch_at",
          "comment": "最近拉取时间",
          "constraint": ""
        },
        {
          "name": "last_fetch_status",
          "comment": "最近拉取状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": ""
    },
    {
      "name": "exchange_rate_raw",
      "comment": "原始汇率",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "source_id",
          "comment": "数据源(派生为空)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "base_currency_id",
          "comment": "基准币种",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_currency_id",
          "comment": "目标币种",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_type",
          "comment": "来源(直接采集/派生)",
          "constraint": ""
        },
        {
          "name": "market_rate",
          "comment": "中间价",
          "constraint": ""
        },
        {
          "name": "fetched_at",
          "comment": "采集/计算时间",
          "constraint": ""
        },
        {
          "name": "expires_at",
          "comment": "失效时间",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态(正常/异常)",
          "constraint": ""
        }
      ],
      "note": "UK: base + target + fetched_at; 直接采集仅USD→X; 派生记录source_id为空"
    },
    {
      "name": "spread_rule",
      "comment": "点差规则",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "base_currency_id",
          "comment": "基准币种(空=全局)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_currency_id",
          "comment": "目标币种(空=全局)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "spread_rate",
          "comment": "点差比例(如0.02)",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "启停状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "全局: base+target=NULL; 方向点差覆盖全局; UK: base+target"
    },
    {
      "name": "exchange_rate_published",
      "comment": "已发布汇率",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "base_currency_id",
          "comment": "基准币种",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_currency_id",
          "comment": "目标币种",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_rate",
          "comment": "中间价(含派生)",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "来源(直接/逆向/交叉)",
          "constraint": ""
        },
        {
          "name": "spread_rate",
          "comment": "应用的点差",
          "constraint": ""
        },
        {
          "name": "published_rate",
          "comment": "平台汇率",
          "constraint": ""
        },
        {
          "name": "publish_type",
          "comment": "发布方式(定时/手动)",
          "constraint": ""
        },
        {
          "name": "published_by",
          "comment": "发布人(系统/运营)",
          "constraint": ""
        },
        {
          "name": "published_at",
          "comment": "发布时间",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态(生效/已替换/停用)",
          "constraint": ""
        }
      ],
      "note": "UK: base + target; 同一有向币种对仅一条生效; 币种停用后置为 disabled_by_currency"
    },
    {
      "name": "rate_change_log",
      "comment": "汇率变动日志",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "snapshot_batch_id",
          "comment": "发布批次号(可空)",
          "constraint": ""
        },
        {
          "name": "target_currency_id",
          "comment": "目标币种",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "operation_type",
          "comment": "操作类型",
          "constraint": ""
        },
        {
          "name": "old_rate",
          "comment": "变更前汇率",
          "constraint": ""
        },
        {
          "name": "new_rate",
          "comment": "变更后汇率",
          "constraint": ""
        },
        {
          "name": "change_reason",
          "comment": "变更原因",
          "constraint": ""
        },
        {
          "name": "operator",
          "comment": "操作人",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "操作时间",
          "constraint": ""
        }
      ],
      "note": "操作类型: 定时发布/手动发布/设置固定汇率/回滚/点差调整/币种停用; 同批次发布共享 batch_id"
    }
  ],
  "relations": [
    {
      "from": "exchange_rate_raw",
      "to": "exchange_rate_source",
      "type": "N:1",
      "label": "来源",
      "color": "#d97706",
      "penwidth": 1.4
    },
    {
      "from": "exchange_rate_raw",
      "to": "currency",
      "type": "N:1",
      "label": "基准/目标币种",
      "color": "#6b7280",
      "penwidth": 1.2
    },
    {
      "from": "spread_rule",
      "to": "currency",
      "type": "N:1",
      "label": "基准/目标币种(可空)",
      "color": "#2563eb",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "exchange_rate_published",
      "to": "currency",
      "type": "N:1",
      "label": "基准/目标币种",
      "color": "#4f46e5",
      "penwidth": 1.4
    },
    {
      "from": "exchange_rate_published",
      "to": "exchange_rate_raw",
      "type": "N:1",
      "label": "加工来源",
      "color": "#2563eb",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "exchange_rate_published",
      "to": "spread_rule",
      "type": "N:1",
      "label": "应用点差",
      "color": "#2563eb",
      "style": "dashed"
    },
    {
      "from": "rate_change_log",
      "to": "currency",
      "type": "N:1",
      "label": "目标币种",
      "color": "#dc2626"
    },
    {
      "from": "rate_change_log",
      "to": "exchange_rate_published",
      "type": "N:1",
      "label": "关联发布记录",
      "color": "#dc2626",
      "penwidth": 1.2,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "naming_alignment": "实体名、字段名与产品架构图保持一致",
    "currency_external": "currency 实体来自币种管理模块，本模块只引用不创建",
    "raw_uniqueness": "exchange_rate_raw 唯一键 (base_currency_id, target_currency_id, fetched_at)；直接采集仅 USD→X，派生记录 source_id 为空",
    "spread_rule_global": "spread_rule 中 base/target 同时为空表示全局点差；方向点差按 priority 覆盖全局",
    "published_active_one": "同一有向币种对在 exchange_rate_published 中仅一条 status=active；币种停用时批量置为 disabled_by_currency",
    "rate_change_log_batch": "同一次发布批次的多币种变动共享 snapshot_batch_id，便于回滚整批"
  }
}
